def evaluateAmount(trx):
    dictFasce = {
        0:[0,1500000],
        1:[1500000,4500000],
        2:[4500000,9000000],
        3:[9000000,14500000],
        4:[14500000,23500000],
        5:[23500000,38500000],
        6:[38500000,62000000],
        7:[62000000,100000000]
    }
    leftTrx = trx
    trxFasce =[]
    for f in range(0,8):
        #if math.floor(trx/dictFasce[f][1]):
        if trx > dictFasce[f][1]:
            trxInFascia = dictFasce[f][1]-dictFasce[f][0]
        else:
            trxInFascia = leftTrx
    
        trxFasce.append(trxInFascia)
        leftTrx = leftTrx - trxInFascia
  
    trxFasce.append(leftTrx)
    return trxFasce

def Diff(arr1,arr2):
    res=[]
    for e in arr1:
        res.append(e-arr2[arr1.index(e)])
    return res

def MyevaluateCurrentBasket(current_trx,previous_trx):
    total_basket= evaluateAmount(float(current_trx+previous_trx))
    previous_basket = evaluateAmount(previous_trx)
    return Diff(total_basket,previous_basket)
    # return total_basket

